mkdir -p /d/Atharva/firstrun/src/firstrun/templates && cat > /d/Atharva/firstrun/src/firstrun/templates/report.html <<'EOF'
<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="color-scheme" content="light">
<title>FirstRun Report</title>
<style>
:root{
  --page:#F5F5F7; --surface:#FBFBFD; --ink:#1D1D1F; --muted:#6E6E73;
  --accent:#0066CC; --pass:#1F8A3B; --fail:#D70015;
  --hair:rgba(29,29,31,.07); --shadow:0 1px 2px rgba(29,29,31,.04),0 8px 28px rgba(29,29,31,.05);
  --pass-bg:#E8F5EC; --fail-bg:#FCE9EB; --neutral-bg:#ECECEF;
  --mono:ui-monospace,"Geist Mono","SF Mono",Menlo,Consolas,monospace;
  --sans:-apple-system,BlinkMacSystemFont,"Geist","Segoe UI",Roboto,Helvetica,Arial,sans-serif;
}
*{box-sizing:border-box}
html{-webkit-text-size-adjust:100%}
body{margin:0;background:var(--page);color:var(--ink);font:400 16px/1.5 var(--sans);
  -webkit-font-smoothing:antialiased}
.wrap{max-width:880px;margin:0 auto;padding:0 16px}
a{color:var(--accent);text-decoration:none}
a:hover{text-decoration:underline}
a:focus-visible,summary:focus-visible{outline:2px solid var(--accent);outline-offset:3px;border-radius:8px}
code,pre,.mono{font-family:var(--mono)}
.missing{color:var(--muted);font-style:italic}

header{padding:56px 0 28px}
.mark{font:700 15px var(--mono);letter-spacing:-.01em}
.mark i{display:inline-block;width:.55em;height:1.05em;background:var(--accent);vertical-align:-.15em;margin-left:2px}
h1{margin:18px 0 12px;font-size:clamp(32px,7vw,52px);line-height:1.05;font-weight:700;letter-spacing:-.04em;max-width:16ch}
.pitch{margin:0;color:var(--muted);font-size:19px;max-width:46ch}
.summary{margin:28px 0 0;font-size:17px}
.summary b{font-weight:600}
.summary .ok{color:var(--pass)} .summary .bad{color:var(--fail)}

h2{font-size:13px;font-weight:600;letter-spacing:.06em;text-transform:uppercase;color:var(--muted);margin:40px 0 12px}

.runs{background:var(--surface);border:1px solid var(--hair);border-radius:22px;box-shadow:var(--shadow);overflow:hidden}
details.run{border-top:1px solid var(--hair)}
details.run:first-child{border-top:0}
details.run>summary{list-style:none;cursor:pointer;padding:18px 20px;display:grid;
  grid-template-columns:1fr auto;gap:4px 12px;align-items:center}
details.run>summary::-webkit-details-marker{display:none}
details.run>summary:hover{background:rgba(29,29,31,.02)}
.target{font-weight:600;font-size:17px;letter-spacing:-.01em;overflow-wrap:anywhere}
.rid{color:var(--muted);font:400 12px var(--mono)}
.meta{grid-column:1/-1;display:flex;flex-wrap:wrap;gap:2px 16px;color:var(--muted);font-size:14px}
.meta b{color:var(--ink);font-weight:500}
.fail-line{grid-column:1/-1;font-size:14px;overflow-wrap:anywhere}
.fail-line code{background:var(--fail-bg);color:var(--fail);padding:1px 6px;border-radius:6px;font-size:13px}

.pill{display:inline-block;padding:3px 12px;border-radius:999px;font-size:13px;font-weight:600;
  background:var(--neutral-bg);color:var(--muted);white-space:nowrap}
.pill.verified{background:var(--pass-bg);color:var(--pass)}
.pill.passed{background:var(--pass-bg);color:var(--pass)}
.pill.failed,.pill.unverified{background:var(--fail-bg);color:var(--fail)}

.detail{padding:4px 20px 22px}
.detail h3{font-size:13px;font-weight:600;color:var(--muted);margin:20px 0 8px}
.tscroll{overflow-x:auto;border:1px solid var(--hair);border-radius:14px;background:#fff}
table{border-collapse:collapse;width:100%;font-size:14px}
th{text-align:left;font-weight:500;color:var(--muted);font-size:12px;padding:8px 12px;border-bottom:1px solid var(--hair);white-space:nowrap}
td{padding:9px 12px;border-bottom:1px solid var(--hair);vertical-align:top}
tr:last-child td{border-bottom:0}
td.cmd{font:400 13px var(--mono);overflow-wrap:anywhere;min-width:200px}
td.num{font-family:var(--mono);white-space:nowrap}
.exit0{color:var(--pass)} .exitn{color:var(--fail);font-weight:600}
tr.broke td{background:var(--fail-bg)}
pre{margin:0;background:#fff;border:1px solid var(--hair);border-radius:14px;padding:12px 14px;
  font-size:13px;line-height:1.5;overflow-x:auto;white-space:pre-wrap;overflow-wrap:anywhere}
.patch{border:1px solid var(--hair);border-radius:14px;background:#fff;padding:12px 14px;font-size:14px}
.patch .old{color:var(--fail)} .patch .new{color:var(--pass)}
.patch code{font-size:13px;overflow-wrap:anywhere}
.patch p{margin:2px 0}
.empty{padding:28px 20px;color:var(--muted)}

.panels{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}
.card{background:var(--surface);border:1px solid var(--hair);border-radius:22px;box-shadow:var(--shadow);padding:20px}
.card img{height:26px;width:auto;display:block;margin-bottom:12px}
.card h3{margin:0 0 2px;font-size:17px;letter-spacing:-.01em}
.card .role{margin:0 0 14px;color:var(--muted);font-size:14px}
.kv{margin:0;font-size:14px}
.kv div{display:flex;justify-content:space-between;gap:12px;padding:6px 0;border-top:1px solid var(--hair)}
.kv dt{color:var(--muted)} .kv dd{margin:0;text-align:right;overflow-wrap:anywhere;min-width:0}

footer{padding:36px 0 56px;color:var(--muted);font-size:13px}
@media(max-width:720px){
  .panels{grid-template-columns:1fr}
  header{padding-top:36px}
  details.run>summary{padding:16px}
  .detail{padding:2px 16px 18px}
}
@media(prefers-reduced-motion:no-preference){
  details.run .detail{animation:rise .4s cubic-bezier(.16,1,.3,1)}
  @keyframes rise{from{opacity:0;transform:translateY(6px)}to{opacity:1;transform:none}}
}
</style>
</head>
<body>
<div class="wrap">
<header>
  <div class="mark">FirstRun<i></i></div>
  <h1>Docs that work (literally).</h1>
  <p class="pitch">FirstRun runs your quickstart in a clean container like a brand-new developer, finds the first step that breaks, and proves the fix with a second clean run.</p>
  <p class="summary">__SUMMARY__</p>
</header>

<main>
<h2>Quickstarts</h2>
<section class="runs" aria-label="Quickstart runs">
__RUNS__
</section>

<h2>Built with</h2>
<section class="panels" aria-label="Tools">
__PANELS__
</section>
</main>

<footer>Built __BUILT__ UTC. Cost is list price, not billed. Every value that reads "missing" was not in the run files.</footer>
</div>
</body>
</html>
EOF
